5	typedef struct rbnode {
6	    char *key;               /* owned copy; NULL on the nil sentinel */
7	    void *value;              /* owned iff value_free != NULL */
8	    struct rbnode *left;
9	    struct rbnode *right;
10	    struct rbnode *parent;
11	    enum { RB_RED, RB_BLACK } color;
12	} rbnode_t;
