47	static void rb_rotate_left(rbtree_t *t, rbnode_t *nodeToRotate)
48	{
49	    rbnode_t *rightChild = nodeToRotate->right;
50	    nodeToRotate->right = rightChild->left;
51	    if (rightChild->left != t->nil)
52	        rightChild->left->parent = nodeToRotate;
53	
54	    rightChild->parent = nodeToRotate->parent;
55	    if (nodeToRotate->parent == t->nil)
56	        t->root = rightChild;
57	    else if (nodeToRotate == nodeToRotate->parent->left)
58	        nodeToRotate->parent->left = rightChild;
59	    else
60	        nodeToRotate->parent->right = rightChild;
61	
62	    rightChild->left = nodeToRotate;
63	    nodeToRotate->parent = rightChild;
64	}
