66	static void rb_rotate_right(rbtree_t *t, rbnode_t *nodeToRotate)
67	{
68	    rbnode_t *leftChild = nodeToRotate->left;
69	    nodeToRotate->left = leftChild->right;
70	    if (leftChild->right != t->nil)
71	        leftChild->right->parent = nodeToRotate;
72	
73	    leftChild->parent = nodeToRotate->parent;
74	    if (nodeToRotate->parent == t->nil)
75	        t->root = leftChild;
76	    else if (nodeToRotate == nodeToRotate->parent->right)
77	        nodeToRotate->parent->right = leftChild;
78	    else
79	        nodeToRotate->parent->left = leftChild;
80	
81	    leftChild->right = nodeToRotate;
82	    nodeToRotate->parent = leftChild;
83	}
