100	/* Leftmost node of the subtree rooted at start: its key is the smallest in
101	 * that subtree, i.e. the in-order successor of whatever node start hangs
102	 * off of. */
103	static rbnode_t *rb_inorder_successor(rbtree_t *t, rbnode_t *start)
104	{
105	    rbnode_t *cur = start;
106	    /* invariant: cur is the smallest-so-far candidate; each step left
107	     * strictly shrinks the subtree still to search. */
108	    while (cur->left != t->nil)
109	        cur = cur->left;
110	    return cur;
111	}
