232	int rb_delete(rbtree_t *t, const char *key)
233	{
234	    rbnode_t *target = t->root;
235	
236	    /* invariant: target is the subtree still to search; strcmp narrows left
237	     * or right each step until an exact match or the nil sentinel is
238	     * reached (same search as rb_find). */
239	    while (target != t->nil) {
240	        int cmp = strcmp(key, target->key);
241	        if (cmp == 0)
242	            break;
243	        target = (cmp < 0) ? target->left : target->right;
244	    }
245	
246	    if (target == t->nil)
247	        return -1;                    /* absent; tree unchanged */
248	
249	    if (target->left == t->nil) {
250	        rb_splice(t, target, target->right);
251	    } else if (target->right == t->nil) {
252	        rb_splice(t, target, target->left);
253	    } else {
254	        rbnode_t *successor = rb_inorder_successor(t, target->right);
255	
256	        if (successor->parent != target) {
257	            rb_splice(t, successor, successor->right);
258	            successor->right = target->right;
259	            successor->right->parent = successor;
260	        }
261	
262	        rb_splice(t, target, successor);
263	        successor->left = target->left;
264	        successor->left->parent = successor;
265	    }
266	
267	    /* TODO: red-black fixup. Removing a black node here can under-populate
268	     * a path and break the equal-black-height invariant; rb_validate will
269	     * reject such trees until fixup lands. */
270	
271	    if (t->value_free)
272	        t->value_free(target->value);
273	    rb_free(target->key);
274	    rb_free(target);
275	    t->size--;
276	    return 0;
277	}
