279	static void rb_foreach_helper(const rbtree_t *t, rbnode_t *checkNode, void (*callerFunction)(const char *key, void *value, void *callerFunctionContext), void (*callerFunctionContext)) {
280	    if (checkNode == t-> nil) return; // Terminate at t->nil
281	    rb_foreach_helper(t, checkNode->left, callerFunction, callerFunctionContext); // Recurse left first (inorder)
282	    callerFunction(checkNode->key, checkNode->value, callerFunctionContext); // Run callerFunction to give them their output
283	    rb_foreach_helper(t, checkNode->right, callerFunction, callerFunctionContext); // Recurse right last (no more left descendants in subtree)
284	}
285	
286	void rb_foreach(const rbtree_t *t,
287	                void (*callerFunction)(const char *key, void *value, void *callerFunctionContext),
288	                void *callerFunctionContext)
289	{
290	    /* TODO: in-order traversal, stopping at t->nil. */
291	    rb_foreach_helper(t, t->root, callerFunction, callerFunctionContext);
292	}
