294	/* Checks order, no-red-red, and black-height for the subtree rooted at x;
295	 * reports 1/0 and writes that subtree's black-height to *bh. lo/hi are the
296	 * open key bound threaded down from ancestors (NULL = unbounded), which is
297	 * what catches an order violation against a distant ancestor, not just x's
298	 * immediate parent. */
299	static int rb_validate_node(const rbtree_t *t, const rbnode_t *x,
300	                             const char *lo, const char *hi, int *bh)
301	{
302	    if (x == t->nil) {
303	        *bh = 0;
304	        return 1;
305	    }
306	
307	    if (lo && strcmp(x->key, lo) <= 0)
308	        return 0;
309	    if (hi && strcmp(x->key, hi) >= 0)
310	        return 0;
311	
312	    if (x->color == RB_RED &&
313	        (x->left->color == RB_RED || x->right->color == RB_RED))
314	        return 0;
315	
316	    int bhL, bhR;
317	    if (!rb_validate_node(t, x->left, lo, x->key, &bhL))
318	        return 0;
319	    if (!rb_validate_node(t, x->right, x->key, hi, &bhR))
320	        return 0;
321	    if (bhL != bhR)
322	        return 0;
323	
324	    *bh = bhL + (x->color == RB_BLACK ? 1 : 0);
325	    return 1;
326	}
327	
328	int rb_validate(const rbtree_t *t)
329	{
330	    if (t->root->color != RB_BLACK)
331	        return -1;
332	
333	    int bh;
334	    return rb_validate_node(t, t->root, NULL, NULL, &bh) ? 0 : -1;
335	}
336	
337	/* Post-order: free a node's children before the node itself, so no pointer
338	 * into freed memory is ever dereferenced. Stops at t->nil, the shared
339	 * sentinel, which rb_destroy frees separately, once, after this returns. */
340	static void rb_destroy_node(rbtree_t *t, rbnode_t *n)
341	{
342	    if (n == t->nil)
343	        return;
344	    rb_destroy_node(t, n->left);
345	    rb_destroy_node(t, n->right);
346	    if (t->value_free)
347	        t->value_free(n->value);
348	    rb_free(n->key);
349	    rb_free(n);
350	}
351	
352	void rb_destroy(rbtree_t *t)
353	{
354	    if (!t)
355	        return;
356	    rb_destroy_node(t, t->root);
357	    rb_free(t->nil);
358	    rb_free(t);
359	}

